$ErrorActionPreference = "Stop"
$root=(Get-Location).Path
$page=Join-Path $root "app\analiz\page.tsx"
$cancel=Join-Path $root "app\api\payments\iyzico\cancel\route.ts"
if (!(Test-Path $page)) { throw "Proje ana klasorunde degilsiniz: app/analiz/page.tsx bulunamadi." }
if (!(Test-Path $cancel)) { throw "iyzico cancel route bulunamadi." }
$stamp=Get-Date -Format "yyyyMMdd-HHmmss"
Copy-Item $page "$page.v27-backup-$stamp" -Force
Copy-Item $cancel "$cancel.v27-backup-$stamp" -Force
$b64=@'

'@
$bytes=[Convert]::FromBase64String($b64.Trim())
$ms=New-Object IO.MemoryStream(,$bytes)
$gz=New-Object IO.Compression.GzipStream($ms,[IO.Compression.CompressionMode]::Decompress)
$out=New-Object IO.MemoryStream
$gz.CopyTo($out); $gz.Dispose(); $ms.Dispose()
[IO.File]::WriteAllBytes($page,$out.ToArray()); $out.Dispose()
$c=Get-Content $cancel -Raw -Encoding UTF8
$c=$c.Replace('String(profile?.status || "") === "canceled"','String(profile?.status || "") === "cancelled"')
$c=$c.Replace('{ ok: true, status: "canceled", alreadyCanceled: true }','{ ok: true, status: "cancelled", alreadyCanceled: true }')
$c=$c.Replace('status: "canceled",','status: "cancelled",`r`n      plan: "standard",')
$c=$c.Replace('{ ok: true, status: "canceled" }','{ ok: true, status: "cancelled" }')
Set-Content $cancel -Value $c -Encoding UTF8
Write-Host "V28 uygulandi. Typecheck..." -ForegroundColor Cyan
npm run typecheck
if ($LASTEXITCODE -ne 0) { throw "Typecheck basarisiz. Backup korundu." }
Write-Host "Build..." -ForegroundColor Cyan
npm run build
if ($LASTEXITCODE -ne 0) { throw "Build basarisiz. Backup korundu." }
Write-Host "V28 BASARILI - kod + typecheck + build tamamlandi." -ForegroundColor Green
